Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "labelColor": "#9AA6B0",
      "labelFont": "Segoe UI",
      "labelFontSize": 10,
      "titleColor": "#9AA6B0",
      "titleFont": "Segoe UI",
      "titleFontWeight": "normal",
      "titleFontSize": 10,
      "domain": false,
      "ticks": false,
      "gridColor": "#2C363E"
    },
    "legend": {
      "labelColor": "#9AA6B0",
      "titleColor": "#9AA6B0",
      "labelFont": "Segoe UI"
    },
    "title": {
      "color": "#C9D3DB",
      "font": "Segoe UI Semibold",
      "fontSize": 12,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 12
    },
    "locale": {
      "number": {
        "decimal": ",",
        "thousands": ".",
        "grouping": [
          3
        ],
        "currency": [
          "R$ ",
          ""
        ]
      },
      "time": {
        "dateTime": "%A, %e de %B de %Y. %X",
        "date": "%d/%m/%Y",
        "time": "%H:%M:%S",
        "periods": [
          "AM",
          "PM"
        ],
        "days": [
          "Domingo",
          "Segunda",
          "Terça",
          "Quarta",
          "Quinta",
          "Sexta",
          "Sábado"
        ],
        "shortDays": [
          "Dom",
          "Seg",
          "Ter",
          "Qua",
          "Qui",
          "Sex",
          "Sáb"
        ],
        "months": [
          "Janeiro",
          "Fevereiro",
          "Março",
          "Abril",
          "Maio",
          "Junho",
          "Julho",
          "Agosto",
          "Setembro",
          "Outubro",
          "Novembro",
          "Dezembro"
        ],
        "shortMonths": [
          "Jan",
          "Fev",
          "Mar",
          "Abr",
          "Mai",
          "Jun",
          "Jul",
          "Ago",
          "Set",
          "Out",
          "Nov",
          "Dez"
        ]
      }
    }
  },
  "title": {
    "text": "Peso no volume × peso no faturamento, por produto"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "fold": [
        "Volume",
        "Faturamento"
      ],
      "as": [
        "medida",
        "valor"
      ]
    }
  ],
  "encoding": {
    "y": {
      "field": "Produto",
      "type": "nominal",
      "sort": null,
      "axis": {
        "title": null,
        "labelColor": "#F2F4F5",
        "labelFontSize": 12,
        "labelPadding": 12
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "#4A5862",
        "strokeWidth": 3
      },
      "encoding": {
        "x": {
          "aggregate": "min",
          "field": "valor",
          "type": "quantitative"
        },
        "x2": {
          "aggregate": "max",
          "field": "valor"
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 200,
        "opacity": 1,
        "stroke": "#1A2026",
        "strokeWidth": 2
      },
      "encoding": {
        "x": {
          "field": "valor",
          "type": "quantitative",
          "axis": {
            "format": ".0%",
            "title": null,
            "grid": true,
            "gridDash": [
              2,
              3
            ],
            "tickCount": 5
          }
        },
        "color": {
          "field": "medida",
          "type": "nominal",
          "scale": {
            "domain": [
              "Volume",
              "Faturamento"
            ],
            "range": [
              "#8A98A4",
              "#FF8C00"
            ]
          },
          "legend": {
            "orient": "top",
            "title": null,
            "direction": "horizontal",
            "symbolType": "circle"
          }
        },
        "tooltip": [
          {
            "field": "Produto"
          },
          {
            "field": "Linha"
          },
          {
            "field": "Familia",
            "title": "Família"
          },
          {
            "field": "Oficial",
            "title": "Produto oficial"
          },
          {
            "field": "medida",
            "title": "Medida"
          },
          {
            "field": "valor",
            "format": ".1%",
            "title": "% do total"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "dy": -14,
        "fontSize": 10
      },
      "encoding": {
        "x": {
          "field": "valor",
          "type": "quantitative"
        },
        "text": {
          "field": "valor",
          "format": ".0%"
        },
        "color": {
          "field": "medida",
          "type": "nominal",
          "scale": {
            "domain": [
              "Volume",
              "Faturamento"
            ],
            "range": [
              "#9AA6B0",
              "#FFB45C"
            ]
          },
          "legend": null
        }
      }
    }
  ],
  "resolve": {
    "scale": {
      "color": "independent"
    }
  }
}'
